const SINAVLAR = [{"kod": "5-s1", "sinif": 5, "ders": "ingilizce", "senaryo": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "bilgi kartı doldurma", "yonerge": "Read the texts quickly. Write in the boxes.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Olivia", "metin": "Hi! I'm Olivia. I'm from Canada. My best friend is Aiko. I love drawing pictures. I'm in the art club.", "aciklama": null}, {"kisi": "Jung", "metin": "My name is Jung. My favourite subject is Maths. I'm from South Korea. I love solving problems. I'm in the chess club.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Name", "Country", "School club"], "satirlar": [["Olivia", {"bosluk": 1}, {"bosluk": 2}], ["Jung", {"bosluk": 3}, {"bosluk": 4}]], "baslik": "STUDENT CARDS"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Canada", "kabul": ["in Canada"], "aciklama": "Olivia'ın metnindeki \"I'm from Canada.\" cümlesi. Ülke \"I'm from ...\" kalıbından sonra gelir."}, {"soru": null, "cevap": "art club", "kabul": ["art", "the art club"], "aciklama": "Olivia'ın metnindeki \"I'm in the art club.\" cümlesi."}, {"soru": null, "cevap": "South Korea", "kabul": ["Korea", "in South Korea"], "aciklama": "Jung'un metnindeki \"I'm from South Korea.\" cümlesi."}, {"soru": null, "cevap": "chess club", "kabul": ["chess", "the chess club"], "aciklama": "Jung'un metnindeki \"I'm in the chess club.\" cümlesi. \"solving problems\" bir etkinliktir; kulüp adı \"in the ... club\" kalıbında geçer."}], "adlar": [], "puanlama": "Alt sorular (kutular) eşit puanlı. Bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz; boş ya da yanlış bilgi 0. Çözüm yolu: Önce iki metne hızlıca göz at; her metinde yalnızca ülkeyi ve kulübü ara (en sevdiği ders, arkadaşı gibi bilgileri atla), bulduğunu kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-5-s1-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Put the sentences in the correct order. Write C, D, E or F in the boxes.", "uyaran": [{"tur": "metin", "metin": "A) OK. Cheers!\nB) Hi, Mehriban! Do you like music?\nC) Great! I like playing the guitar. I'm in the music club.\nD) It's downstairs. Let's go together.\nE) Yes, I do. I love singing songs.\nF) Cool! Where is the music club?", "baslik": "At School"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "A"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "Pedro \"Do you like music?\" diye sorar; cevap \"Yes, I do.\" ile başlayan E cümlesidir."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "Pedro \"Great!\" der ve kendini anlatır (guitar, music club). Bu cümle E'den sonra gelir, çünkü Mehriban'ın müzik sevdiğine karşılık verir."}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "Mehriban \"music club\" sözünü duyunca \"Where is the music club?\" diye sorar; bu soru C'den sonra gelir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "\"Where...?\" sorusunun cevabı \"It's downstairs.\" cümlesidir (D); hemen ardından \"Let's go together.\" gelir."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan; yanlış ya da boş 0. Çözüm yolu: İlk ve son cümle verilmiş. Her soruya cevap olan cümleyi bul (Do you like...? → Yes, I do. Where...? → It's downstairs) ve sırayla yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-5-s1-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "kolay", "soru_tipi": "karışık harflerden kelime", "yonerge": "Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "We sing songs in the ........ club. (i u c m s)", "cevap": "music", "kabul": [], "aciklama": "Harfler: m-u-s-i-c (5 harf). Şarkı söylenen kulüp \"music club\" (müzik kulübü)."}, {"soru": "Jack is in the ........ club. (a m d r a)", "cevap": "drama", "kabul": [], "aciklama": "Harfler: d-r-a-m-a (5 harf). \"drama club\" (tiyatro kulübü); \"a\" harfi iki kez kullanılır."}, {"soru": "The ........ makes food in the canteen. (o k c o)", "cevap": "cook", "kabul": [], "aciklama": "Harfler: c-o-o-k (4 harf). Kantinde yemek yapan kişi aşçıdır: cook; \"o\" harfi iki kez kullanılır."}, {"soru": "We do experiments in the ........ lab. (n c e i s c e)", "cevap": "science", "kabul": [], "aciklama": "Harfler: s-c-i-e-n-c-e (7 harf). Deney yapılan laboratuvar science lab; \"c\" ve \"e\" ikişer kez kullanılır."}], "adlar": [], "puanlama": "Alt sorular (kelimeler) eşit puanlı. Kelime doğru yazılmışsa tam puan; tek harf hatası yarım puan; boş ya da yanlış kelime 0. Çözüm yolu: İpucu cümlesini oku, kelimeyi düşün ve kutulara yaz; kesişen harfler cevabını kontrol etmene yardım eder.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["makes:SARTLI", "sing:KOK"]}, "ornek": "We play ........ in the club. (s h c e s) → chess"}, {"id": "HZ-5-s1-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "hata düzeltme", "yonerge": "One word in each sentence is false. Write the correct sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "They is in the art club.", "cevap": "They are in the art club.", "kabul": [], "aciklama": "\"They\" ile \"are\" kullanılır; \"is\" yalnız he / she / it ile gelir."}, {"soru": "Jack is in an music club.", "cevap": "Jack is in a music club.", "kabul": [], "aciklama": "\"Music\" ünsüz sesiyle (m) başlar, bu yüzden \"a\" kullanılır; \"an\" ünlü sesi (a, e, i, o, u) için."}, {"soru": "You mustn't runs in the library.", "cevap": "You mustn't run in the library.", "kabul": [], "aciklama": "\"mustn't\" ve \"can't\" den sonra fiil yalın halde gelir: eat."}, {"soru": "Do you likes playing chess?", "cevap": "Do you like playing chess?", "kabul": [], "aciklama": "\"Do you\" ile başlayan soruda fiil yalın halde kalır: like. \"-s\" yalnız he / she / it cümlelerinde olur."}, {"soru": "Me favourite subject is Maths.", "cevap": "My favourite subject is Maths.", "kabul": [], "aciklama": "İyelik \"my\" (benim) ile yapılır. \"My favourite subject is ...\" kalıbı."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru cümle tam puan; hata düzeltilmiş ama başka bir yazım hatası varsa yarım puan; hata düzeltilmemişse ya da boşsa 0. Çözüm yolu: Cümleyi dikkatle oku, yanlış kelimeyi bul (is/are, a/an, fiilin biçimi, my/me) ve tüm cümleyi doğru yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["runs:SARTLI", "sentence:KOK", "word:KOK"]}, "ornek": "Wear you goggles. → Wear your goggles."}, {"id": "HZ-5-s1-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "örnek metinle benzer metin yazma", "yonerge": "Read the example. Look at the card. Write about Selin. Use \"She\".", "uyaran": [{"tur": "metin", "metin": "This is Roberto. He is from Italy. He is in the science club. He likes doing experiments.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Name", "Selin"], ["Country", "Türkiye"], ["School club", "film club"], ["Likes", "watching films"]], "baslik": "STUDENT CARD"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-5-s1-05.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(name)", "cevap": "This is Selin.", "kabul": ["She is Selin."], "aciklama": "Örnekteki \"This is Roberto.\" cümlesi gibi: \"This is\" + kartın Name satırı."}, {"soru": "(country)", "cevap": "She is from Türkiye.", "kabul": ["Selin is from Türkiye."], "aciklama": "Örnekteki \"He is from Italy.\" gibi; Selin kız olduğu için \"She is from\" + Country satırı."}, {"soru": "(club)", "cevap": "She is in the film club.", "kabul": ["Selin is in the film club.", "She is a member of the film club."], "aciklama": "Örnekteki \"He is in the science club.\" gibi: \"She is in the\" + School club satırı."}, {"soru": "(likes)", "cevap": "She likes watching films.", "kabul": ["She loves watching films.", "Selin likes watching films."], "aciklama": "Örnekteki \"He likes doing experiments.\" gibi: \"She likes\" + Likes satırı."}], "adlar": ["Selin"], "puanlama": "Alt sorular (dört cümle) eşit puanlı. Karttaki bilgiyi doğru aktaran, anlaşılır cümle tam puan; bilgi doğru ama belirgin dil hatası (He, is eksik vb.) yarım puan; boş ya da yanlış bilgi 0. Anahtardakiler örnektir. Çözüm yolu: Önce örnek metne bak; her satırda ipucuna (name, country, club, likes) uygun kart bilgisini bul ve örnekteki gibi yaz. Selin kız olduğu için \"She\" kullan.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["films:SARTLI", "loves:SARTLI", "watching:SARTLI"]}}]}, {"kod": "5-s1s", "sinif": 5, "ders": "secmeli", "senaryo": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1s-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts quickly. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Pierre", "metin": "Hi! I'm Pierre. I'm from France. I love playing the piano. I'm in the music club.", "aciklama": null}, {"kisi": "Chen", "metin": "My name is Chen. I'm from China. I do experiments in the lab. I'm in the science club.", "aciklama": null}, {"kisi": "Carol", "metin": "Hey! I'm Carol. I'm from Canada. I love playing chess. I'm in the chess club.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I am a member of the science club.\"", "cevap": "Chen", "kabul": [], "aciklama": "Chen \"I'm in the science club\" der. Fen kulübünde olan tek kişi Chen'dir; Pierre müzik, Carol satranç kulübündedir."}, {"soru": "\"Canada is my country.\"", "cevap": "Carol", "kabul": [], "aciklama": "Carol \"I'm from Canada\" der. Ülke \"I'm from ...\" kalıbından sonra gelir; Pierre Fransa'dan, Chen Çin'denir."}, {"soru": "\"I can play the piano.\"", "cevap": "Pierre", "kabul": [], "aciklama": "Pierre \"I love playing the piano\" der. Piyano çalan tek kişi Pierre'dir; metinlerde piyanodan başka söz eden yoktur."}, {"soru": "\"I like chess.\"", "cevap": "Carol", "kabul": [], "aciklama": "Carol \"I love playing chess\" der. Satranç sevdiği için hem \"chess club\" hem de bu cümle Carol'a aittir. Chen yazmak (Chen deney yapar)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: doğru kişinin adı (isimde küçük yazım hatası kabul edilir). Yanlış / boş: 0. Çözüm yolu: Önce üç kısa metni oku ve her kişinin ülkesini, kulübünü, sevdiği şeyi not al. Sonra verilen cümlenin hangi bilgiye uyduğunu bul ve o kişinin adını yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["says:SARTLI"]}}, {"id": "HZ-5-s1s-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. These sentences are false. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi! I'm Noah. I'm from Australia. I'm a student at this school. I like surfing. I'm in the sports club. Mr Harris is our coach. We play volleyball in the sports field.", "baslik": "Noah's School"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-5-s1s-02.jpg", "yerlesim": "yan"}, "alt_sorular": [{"soru": "Noah likes drawing pictures.", "cevap": "Noah likes surfing.", "kabul": ["He likes surfing."], "aciklama": "Metindeki \"I like surfing.\" cümlesi. Noah'ın sevdiği şey surfing'dir."}, {"soru": "Mr Adams is the coach.", "cevap": "Mr Harris is the coach.", "kabul": ["Mr Harris is their coach."], "aciklama": "Metindeki \"Mr Harris is our coach.\" cümlesi. Antrenör Mr Harris'tir; Mr Adams metinde geçmez."}, {"soru": "Noah is from Italy.", "cevap": "Noah is from Australia.", "kabul": ["He is from Australia."], "aciklama": "Metindeki \"I'm from Australia.\" cümlesi. Ülke \"from\" sözcüğünden sonra yazılır; sadece Italy sözcüğü Australia ile değiştirilir."}, {"soru": "Noah is in the art club.", "cevap": "Noah is in the sports club.", "kabul": ["He is in the sports club."], "aciklama": "Metindeki \"I'm in the sports club.\" cümlesi. Kulüp adı \"in the ... club\" kalıbında geçer."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: yanlış bilgi metne göre doğru düzeltilmiş cümle. Kısmi (yarım puan): düzeltme doğru ama cümlede belirgin dil hatası var. Yanlış bilgi düzeltilmemişse ya da boşsa 0. Çözüm yolu: Önce metni oku; her cümleyi metindeki bilgiyle karşılaştır, yanlış kısmı metindeki doğru bilgiyle değiştirip cümleyi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["noah's:SARTLI", "text:KOK"]}}, {"id": "HZ-5-s1s-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "orta", "soru_tipi": "ipucusuz tamamlama", "yonerge": "Write one word for each sentence.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Excuse .......... ! I am new at school.", "cevap": "me", "kabul": [], "aciklama": "\"Excuse me!\" birine seslenirken kullanılan kalıptır (afedersiniz). Kitaptaki \"Excuse me! Where is the science club?\" cümlesinde olduğu gibi."}, {"soru": "Don't make .......... in the library.", "cevap": "noise", "kabul": [], "aciklama": "\"make noise\" = gürültü yapmak. Kütüphanede gürültü yapmak yasaktır; kitaptaki kural konusundan (library rules)."}, {"soru": "Let's .......... started!", "cevap": "get", "kabul": [], "aciklama": "\"Let's get started!\" (Haydi başlayalım!) kitaptaki sosyal kalıptır."}, {"soru": "Students do .......... in the science lab.", "cevap": "experiments", "kabul": ["experiment"], "aciklama": "Fen laboratuvarında yapılan şey deneydir: \"do experiments\". Kitaptaki \"doing experiments\" ve \"science lab\" ifadelerinden."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelime doğru yazılmış. Kısmi (yarım puan): tek harf hatası. Yanlış / boş: 0. Çözüm yolu: Cümleyi baştan sona oku; derste öğrendiğin kalıbı (Nice to meet you gibi) hatırla ve boşluğa uyan tek kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["experiment:KOK", "sentence:KOK", "word:KOK"]}, "ornek": "Welcome .......... our school! → to"}, {"id": "HZ-5-s1s-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "kelimeleri sıraya koyup cümle yazma", "yonerge": "Put the words in the correct order. Write the sentences.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mary / is / where / from", "cevap": "Where is Mary from?", "kabul": [], "aciklama": "Soru sözcüğü (Where) başa gelir, sonra is ve kişi adı, en sonda from. Kitaptaki \"Where is Mary from?\" kalıbı. Soru işareti (?) eksikliği puan kırdırmaz; kelimelerden soru cümlesi çıkar."}, {"soru": "food / eat / in the library / can't / you", "cevap": "You can't eat food in the library.", "kabul": [], "aciklama": "Önce özne (You), sonra can't ve yalın fiil (eat), en sonda yer: \"You can't + fiil + yer\"."}, {"soru": "reading books / do / like / you", "cevap": "Do you like reading books?", "kabul": [], "aciklama": "Soru \"Do you like\" ile başlar, sonra -ing'li etkinlik gelir: \"Do you like + -ing?\". Kitaptaki \"Do you like reading books?\" kalıbı."}, {"soru": "in / the drama club / is / Pedro", "cevap": "Pedro is in the drama club.", "kabul": ["Is Pedro in the drama club?"], "aciklama": "Önce özne (Pedro), sonra is, sonra \"in the drama club\": \"Pedro is in the ... club\". Aynı kelimelerle \"Is Pedro in the drama club?\" sorusu da doğrudur ve kabul edilir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelimeler doğru sırada, cümle doğru (büyük harf ve nokta eksikliği puan kırdırmaz). Kısmi (yarım puan): sıra doğru ama bir kelime eksik / fazla ya da belirgin yazım hatası var. Sıra yanlışsa ya da boşsa 0. Çözüm yolu: Önce özneyi (Who / kişi) ya da soru sözcüğünü bul, sonra fiili yerleştir ve kalan kelimeleri anlamlı bir cümle olacak şekilde sırala.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(the rules / follow) → Follow the rules."}, {"id": "HZ-5-s1s-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "notlardan afiş", "yonerge": "Read the notes. Then write the poster for the new club in the boxes.", "uyaran": [{"tur": "metin", "metin": "Origami club, on Thursday, in the classroom. Students fold paper and colour pictures. The teacher is Ms Carol.", "baslik": "Notes"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Title", {"ornek": "Origami Club"}], ["Day", {"bosluk": 1}], ["Place", {"bosluk": 2}], ["Activities", {"bosluk": 3}], ["Teacher", {"bosluk": 4}]], "baslik": "POSTER"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Thursday", "kabul": ["on Thursday"], "aciklama": "Notlarda \"on Thursday\" yazar. Day (gün) satırına günün adı yazılır. Title satırının cevabıdır)."}, {"soru": null, "cevap": "in the classroom", "kabul": ["the classroom", "classroom"], "aciklama": "Notlarda \"in the classroom\" yazar. Place (yer) satırına kulübün yapıldığı yer yazılır."}, {"soru": null, "cevap": "folding paper and colouring pictures", "kabul": ["folding paper and colouring pictures.", "Students fold paper and colour pictures.", "fold paper and colour pictures"], "aciklama": "Notlarda \"Students fold paper and colour pictures.\" cümlesi var. Activities (etkinlikler) satırına öğrencilerin yaptığı iki iş yazılır."}, {"soru": null, "cevap": "Ms Carol", "kabul": ["Carol", "The teacher is Ms Carol."], "aciklama": "Notlarda \"The teacher is Ms Carol.\" yazar. Teacher (öğretmen) satırına öğretmenin adı yazılır."}], "adlar": ["Carol"], "puanlama": "Kutular eşit puanlı. Notlardaki bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz. Yanlış bilgi / boş: 0. Anahtardakiler örnektir. Çözüm yolu: Önce notları oku; Title satırındaki örneğe bakarak her satırın ne istediğini anla (Day = gün, Place = yer, Activities = etkinlik, Teacher = öğretmen) ve notlardaki ilgili bilgiyi kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fold:KOK", "notes:SARTLI", "place:KOK", "title:KOK"]}}]}, {"kod": "6-s1", "sinif": 6, "ders": "ingilizce", "senaryo": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-6-s1-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "duyurunun yerini bulma", "yonerge": "Read the notices. Where can you see them? Write the places.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Notice 1", "metin": "Borrow storybooks here. Return the books on Friday.", "aciklama": null}, {"kisi": "Notice 2", "metin": "Do experiments here. Listen to your teacher carefully.", "aciklama": null}, {"kisi": "Notice 3", "metin": "Sports Day is on Friday. Run in the race here.", "aciklama": null}, {"kisi": "Notice 4", "metin": "Lessons start at 8:30. Sit at your desk. Do not forget your bag.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(1)", "cevap": "library", "kabul": ["in the library", "the library"], "aciklama": "\"Borrow storybooks\" (kitap ödünç al) ve \"Return the books\" (kitapları geri ver) kütüphanede yapılır."}, {"soru": "(2)", "cevap": "lab", "kabul": ["in the lab", "science lab", "in the science lab"], "aciklama": "\"Do experiments\" (deney yap) laboratuvarda yapılır."}, {"soru": "(3)", "cevap": "sports field", "kabul": ["in the sports field", "the sports field", "playground"], "aciklama": "\"Sports Day\" ve \"Run in the race\" (yarışta koş) spor sahasını gösterir."}, {"soru": "(4)", "cevap": "classroom", "kabul": ["in the classroom", "the classroom", "class"], "aciklama": "\"Lessons start\" (dersler başlar), \"Sit at your desk\" (sırana otur) sınıfı gösterir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: duyuruya uygun doğru yer (yazım hatası kırılmaz). Kısmi: yok. Boş / yanlış yer: 0. Çözüm: Her duyuruyu oku; eşya (books, desk), eylem (do experiments, run) ve zaman ipuçlarına bak, bu şeylerin yapıldığı yeri yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["notices:SARTLI", "run:KOK"]}}, {"id": "HZ-6-s1-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "paragraf cümlelerini sıralama", "yonerge": "The sentences are not in the correct order. Write the correct order.", "uyaran": [{"tur": "metin", "metin": "A) After the lessons, Hale reads books in the library.\nB) In the morning, Hale eats breakfast with her mum.\nC) In the evening, she does her homework.\nD) Then, she goes to school by bus.\nE) At 12:00, she eats lunch in the lunch hall.", "baslik": "Hale's Day"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "D", "kabul": [], "aciklama": "B (sabah kahvaltı) örnektir; kahvaltıdan sonra \"Then, she goes to school by bus\" gelir. \"Then\" (sonra) kahvaltıdan sonraki adımı gösterir."}, {"soru": null, "cevap": "E", "kabul": [], "aciklama": "Okula varınca saat 12:00 olur ve Hale öğle yemeği yer: \"At 12:00, she eats lunch\". A yazmak (A dersten sonradır)."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "Öğle yemeğinden sonra dersler biter: \"After the lessons\" (derslerden sonra). Hale kütüphanede kitap okur."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "Gün \"In the evening\" (akşam) ile biter: Hale ödevini yapar."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Tam: doğru harf. Yanlış / boş: 0. Çözüm: Önce bütün cümleleri oku. Zaman sözcüklerine bak (In the morning, At 12:00, After the lessons, In the evening) ve günü sabahtan akşama sırala.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["eats:SARTLI", "goes:SARTLI", "hale's:SARTLI"]}}, {"id": "HZ-6-s1-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "karışık harflerden kelime", "yonerge": "Complete the sentences. Write the words in the correct order.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Defne gives a ........ at the school ceremony. (c h e e s p)", "cevap": "speech", "kabul": [], "aciklama": "Harfler: s-p-e-e-c-h (6 harf). \"gives a speech\" (konuşma yapar) kalıbı. Yazım önemlidir; \"e\" iki kez kullanılır."}, {"soru": "The ........ sings songs on the stage. (o i c h r)", "cevap": "choir", "kabul": [], "aciklama": "Harfler: c-h-o-i-r (5 harf). \"choir\" (koro) şarkı söyleyen gruptur."}, {"soru": "We line up in the school ........ every morning. (d a r g e n)", "cevap": "garden", "kabul": [], "aciklama": "Harfler: g-a-r-d-e-n (6 harf). \"school garden\" (okul bahçesi)."}, {"soru": "Our ........ explains the lesson clearly. (c h a t e r e)", "cevap": "teacher", "kabul": [], "aciklama": "Harfler: t-e-a-c-h-e-r (7 harf). Dersi açıklayan kişi öğretmendir; \"e\" iki kez kullanılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelime doğru yazılmış. Kısmi (yarım puan): tek harf hatası. Yanlış / boş: 0. Çözüm: Cümleyi oku, boşluğa hangi kelimenin uyduğunu düşün, sonra harfleri sırala ve harf sayısını kontrol et.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sings:SARTLI"]}, "ornek": "Students read ........ in the library. (o k s b o) → books"}, {"id": "HZ-6-s1-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "sıklık zarfını yerleştirme", "yonerge": "Write the sentences again. Use the word after each sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Students are quiet in the library. (always)", "cevap": "Students are always quiet in the library.", "kabul": [], "aciklama": "\"be\" (are) fiilinden SONRA gelir: are + always."}, {"soru": "Fatih reads storybooks in the reading corner. (often)", "cevap": "Fatih often reads storybooks in the reading corner.", "kabul": ["Often Fatih reads storybooks in the reading corner."], "aciklama": "Sıklık zarfı ana fiilden ÖNCE gelir: often + reads."}, {"soru": "Our teacher gives us science projects. (sometimes)", "cevap": "Our teacher sometimes gives us science projects.", "kabul": ["Sometimes our teacher gives us science projects."], "aciklama": "Zarf ana fiilden önce gelir: teacher + sometimes + gives. Cümle başında \"Sometimes\" da kabul edilir."}, {"soru": "Kyle walks to school. (never)", "cevap": "Kyle never walks to school.", "kabul": [], "aciklama": "\"never\" ana fiilden önce gelir: never + walks."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: zarf doğru yerde, cümle doğru. Kısmi (yarım puan): zarf doğru ama küçük yazım / eksik sözcük hatası. Zarf yanlış yerde / boş: 0. Çözüm: Fiil \"am / is / are\" ise zarf ondan SONRA, diğer fiillerde (reads, gives, walks) fiilden ÖNCE gelir.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["walks:SARTLI"]}, "ornek": "We eat lunch at school. (usually) → We usually eat lunch at school."}, {"id": "HZ-6-s1-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W3", "zorluk": "orta", "soru_tipi": "notlardan benzer metin yazma", "yonerge": "Read the example. Look at the notes. Write Mehmet's text.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Defne. I always walk to school. I usually eat lunch in the garden. I often sing in the choir. I never forget my homework.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["Mehmet", "How often"], "satirlar": [["go to school by bus", "always"], ["eat lunch in the lunch hall", "usually"], ["read storybooks in the library", "often"], ["come to school late", "never"]], "baslik": "Notes"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-6-s1-05.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "Hi, I'm Mehmet. I ", "cevap": "always go to school by bus.", "kabul": [], "aciklama": "Notlardaki ilk satır: \"go to school by bus\" + always. Örnekteki gibi birinci kişi: \"I always go...\"."}, {"soru": "I ", "cevap": "usually eat lunch in the lunch hall.", "kabul": [], "aciklama": "Notlardaki ikinci satır: \"eat lunch in the lunch hall\" + usually. Zarf fiilden önce gelir."}, {"soru": "I ", "cevap": "often read storybooks in the library.", "kabul": [], "aciklama": "Notlardaki üçüncü satır: \"read storybooks in the library\" + often."}, {"soru": "I ", "cevap": "never come to school late.", "kabul": [], "aciklama": "Notlardaki son satır: \"come to school late\" + never. \"never\" ile fiil olumlu kalır (don't eklenmez)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: notlardaki bilgi doğru, sıklık sözcüğü doğru yerde, cümle anlaşılır. Kısmi (yarım puan): bilgi doğru ama zarf yanlış yerde ya da belirgin dil hatası. Bilgi yanlış / boş: 0. Çözüm: Önce Example metnine bak; her satırda zarf, \"I\" ile fiil arasındadır. Sonra notlardaki her satırı aynı biçimde yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}}]}, {"kod": "6-s5", "sinif": 6, "ders": "secmeli", "senaryo": 5, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 2}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.W4", "tema": "School Life", "metin": "Students can individually construct/form content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations”.", "adet": 1}], "sorular": [{"id": "HZ-6-s5-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts quickly. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Salih", "metin": "I wake up early. I eat breakfast with my mum. I go to school by bus.", "aciklama": null}, {"kisi": "Hale", "metin": "I like music. I sing in the choir. We sing the National Anthem at the ceremony.", "aciklama": null}, {"kisi": "Sinan", "metin": "I do my homework in the evening. I read storybooks at home.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I take the bus to school.\"", "cevap": "Salih", "kabul": [], "aciklama": "Salih \"I go to school by bus\" der. Otobüsle okula giden tek kişi Salih'tir; Hale ve Sinan otobüsten söz etmez."}, {"soru": "\"I sing with my friends in the choir.\"", "cevap": "Hale", "kabul": [], "aciklama": "Hale \"I sing in the choir\" der. Koroda şarkı söyleyen tek kişi Hale'dir."}, {"soru": "\"I study at home in the evening.\"", "cevap": "Sinan", "kabul": [], "aciklama": "Sinan \"I do my homework in the evening\" der. Akşam ödev yapan kişi Sinan'dır; Salih ve Hale akşamdan söz etmez."}, {"soru": "\"My mum and I eat together in the morning.\"", "cevap": "Salih", "kabul": [], "aciklama": "Salih \"I eat breakfast with my mum\" der. Anne ile kahvaltı eden tek kişi Salih'tir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. İsimde küçük yazım hatası kabul edilir. Çözüm: önce üç kısa metni oku, sonra her cümlenin hangi kişinin metnindeki bilgiye uyduğunu bul.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}}, {"id": "HZ-6-s5-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text quickly. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi, I am Sinan. I help in our school library. I always smile when I greet the students. On Mondays, students borrow books. They return them on Fridays. The library is quiet, so students read silently.", "baslik": "Our School Library"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": "HZ-6-s5-02.jpg", "yerlesim": "yan"}, "alt_sorular": [{"soru": "Sinan greets the students with a ......... .", "cevap": "smile", "kabul": [], "aciklama": "Metindeki \"I always smile when I greet the students\" cümlesi. Sinan öğrencileri gülümseyerek karşılar."}, {"soru": "Students take books home on ......... .", "cevap": "Mondays", "kabul": ["Monday"], "aciklama": "Metindeki \"On Mondays, students borrow books\" cümlesi. \"take books home\" ile \"borrow books\" aynı işi anlatır."}, {"soru": "Students bring the books to the library on ......... .", "cevap": "Fridays", "kabul": ["Friday"], "aciklama": "Metindeki \"They return them on Fridays\" cümlesi. Kitapları getirmek ile geri vermek (return) aynı şeydir. Mondays yazmak."}, {"soru": "Students read ......... in the library.", "cevap": "silently", "kabul": [], "aciklama": "Metindeki \"students read silently\" cümlesi."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cevap metinde geçen kelimedir; yazım önemli, tek harf hatası yarım puan. Çözüm: cümlenin anlamını düşün, sonra metinde aynı bilgiyi anlatan cümleyi bulup kaldığı boşluğa uyan kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fridays:SARTLI", "mondays:SARTLI"]}}, {"id": "HZ-6-s5-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Answer the questions.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Erol. I walk to school with my sister, Hale. We always arrive early. I am in the school choir. We sing on Fridays. After school, I usually study in the library.", "baslik": "Erol's Day"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Does Erol walk to school with his brother?", "cevap": "No, he does not. He walks to school with his sister.", "kabul": ["No. He walks with his sister."], "aciklama": "Metindeki \"I walk to school with my sister, Hale\" cümlesi. Erol kız kardeşiyle yürür, bu yüzden cevap \"No\" olur ve \"sister\" ile düzeltilir."}, {"soru": "Is Erol in the school choir?", "cevap": "Yes, he is.", "kabul": ["Yes.", "Yes, he is in the school choir."], "aciklama": "Metindeki \"I am in the school choir\" cümlesi. Bilgi doğru olduğu için cevap \"Yes\" olur, düzeltme gerekmez."}, {"soru": "Does the choir sing on Mondays?", "cevap": "No, it does not. It sings on Fridays.", "kabul": ["No. It sings on Fridays."], "aciklama": "Metindeki \"We sing on Fridays\" cümlesi. Gün yanlış olduğu için \"No\" yazılıp doğru gün (Fridays) eklenir."}, {"soru": "Does Erol study in the library before school?", "cevap": "No, he does not. He studies in the library after school.", "kabul": ["No. He studies after school."], "aciklama": "Metindeki \"After school, I usually study in the library\" cümlesi. Zaman yanlıştır (before), doğrusu after school."}, {"soru": "Does Erol arrive early?", "cevap": "Yes, he does.", "kabul": ["Yes.", "Yes, he arrives early."], "aciklama": "Metindeki \"We always arrive early\" cümlesi. \"We\" Erol ve Hale'dir; Erol erken gelir, cevap \"Yes\"."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Yes/No cevabı doğru ve cevap metne uygunsa tam puan; \"No\" cevabında düzeltme eksikse yarım puan. Yazım ve dilbilgisi hatası puan kırdırmaz. Çözüm: önce metinde sorunun bilgisini bul; bilgi aynıysa \"Yes\", farklıysa \"No\" yazıp doğru bilgiyi ekle.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["arrives:SARTLI", "erol's:SARTLI", "fridays:SARTLI", "mondays:SARTLI", "sing:KOK", "sings:SARTLI", "walks:SARTLI"]}, "ornek": "Does Erol go to school by bus? → No, he does not. He walks to school."}, {"id": "HZ-6-s5-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "ipucusuz tamamlama", "yonerge": "Write one word for each sentence.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Students borrow books from the ........ .", "cevap": "library", "kabul": ["school library"], "aciklama": "Kitap ödünç alınan yer kütüphanedir: \"borrow books from the library\"."}, {"soru": "We sing the National ........ at the ceremony.", "cevap": "Anthem", "kabul": ["anthem"], "aciklama": "\"National Anthem\" (İstiklal Marşı gibi ulusal marş) tören kalıbıdır: \"sing the National Anthem\"."}, {"soru": "Hale gives a ........ at the school ceremony.", "cevap": "speech", "kabul": [], "aciklama": "\"give a speech\" (konuşma yapmak) kalıbı; törende konuşma yapılır."}, {"soru": "Please be ........ in the library.", "cevap": "quiet", "kabul": [], "aciklama": "Kütüphane kuralı: \"be quiet\" (sessiz ol)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime sorusu: yazım önemli, tek harf hatası yarım puan. Çözüm: ipucu cümlesini oku, kelimeyi bul ve kutulara harf harf yaz; ortak harfler diğer kelimeyi doğrulamanıza yardım eder.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}, "ornek": "We eat ........ at 12:00. → lunch"}, {"id": "HZ-6-s5-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "orta", "soru_tipi": "kelimeyle cümle kurma", "yonerge": "Write a sentence with each word.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": "sira"}, "alt_sorular": [{"soru": "(canteen)", "cevap": "I eat lunch in the canteen.", "kabul": ["We have lunch in the school canteen."], "aciklama": "\"canteen\" okuldaki yemek yeri anlamında kullanılmalı. Örnek: \"I eat lunch in the canteen.\"", "foto": "HZ-6-s5-05_1.jpg"}, {"soru": "(assembly)", "cevap": "There is an assembly on Friday.", "kabul": ["The students are in the assembly."], "aciklama": "\"assembly\" öğretmen ve öğrencilerin toplandığı toplantıdır. Örnek: \"There is an assembly on Friday.\"", "foto": "HZ-6-s5-05_2.jpg"}, {"soru": "(borrow)", "cevap": "I borrow books from the library.", "kabul": ["Students borrow storybooks."], "aciklama": "\"borrow\" ödünç almak demektir; fiil olarak kullanılmalı. Örnek: \"I borrow books from the library.\" I / students ise -s yok).", "foto": "HZ-6-s5-05_3.jpg"}, {"soru": "(poem)", "cevap": "I read a poem at the ceremony.", "kabul": ["Hale reads a poem in the class."], "aciklama": "\"poem\" şiir demektir. Örnek: \"I read a poem at the ceremony.\"", "foto": "HZ-6-s5-05_4.jpg"}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime anlamına uygun kullanılmışsa tam puan; küçük yazım hatası kırılmaz, kelime yanlış kullanılmışsa puan yok. Çözüm: kelimenin anlamını düşün ve onunla okulla ilgili kısa, doğru bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(teacher) → The teacher helps the students."}, {"id": "HZ-6-s5-06", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "hata düzeltme", "yonerge": "There is one mistake in each sentence. Write the correct sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Salih always wake up early.", "cevap": "Salih always wakes up early.", "kabul": [], "aciklama": "Özne Salih (3. tekil) olduğu için geniş zamanda fiile -s gelir: wakes."}, {"soru": "My dad sometimes helps I with my homework.", "cevap": "My dad sometimes helps me with my homework.", "kabul": [], "aciklama": "Fiilden sonra nesne zamiri kullanılır: I yerine me."}, {"soru": "There is many students in the lunch hall.", "cevap": "There are many students in the lunch hall.", "kabul": [], "aciklama": "\"many students\" çoğuldur, bu yüzden \"There are\" kullanılır."}, {"soru": "Hale and Sinan sometimes is late for the ceremony.", "cevap": "Hale and Sinan sometimes are late for the ceremony.", "kabul": [], "aciklama": "İki kişi (Hale and Sinan) çoğuldur, bu yüzden is yerine are gelir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Dilbilgisi sorusu: hedef yapı doğru olmalı; küçük yazım hatası puan kırdırmaz. Çözüm: cümleyi dikkatle oku, yapıyı (fiil biçimi, zamir, there is / are) kontrol et ve yanlış olan tek kısmı düzelt.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "Mum make breakfast. → Mum makes breakfast."}, {"id": "HZ-6-s5-07", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "birinci kişiyi üçüncü kişiye çevirme", "yonerge": "Read Hale's sentences. Write the sentences about Hale.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "I usually walk to school with my brother.", "cevap": "Hale usually walks to school with her brother.", "kabul": [], "baslangic": "Hale", "aciklama": "I yerine Hale yazılır, fiile -s gelir (walks), my yerine her olur."}, {"soru": "I often read books in the library.", "cevap": "Hale often reads books in the library.", "kabul": [], "baslangic": "Hale", "aciklama": "3. tekil kişide read fiiline -s eklenir: reads. Sıklık zarfı (often) fiilden önce kalır."}, {"soru": "I sometimes help my friends with my homework.", "cevap": "Hale sometimes helps her friends with her homework.", "kabul": [], "baslangic": "Hale", "aciklama": "helps (-s) yazılır ve her my her olur: her friends, her homework."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Fiil biçimi (-s) ve sahiplik sözcüğü (her) doğruysa tam puan; küçük yazım hatası puan kırdırmaz. Çözüm: \"I\" yerine kişinin adını yaz, fiile 3. tekil -s ekle, my yerine her kullan.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["goes:SARTLI", "hale's:SARTLI", "walks:SARTLI"]}, "ornek": "I go to school by bus. → Hale goes to school by bus."}, {"id": "HZ-6-s5-08", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W4", "zorluk": "orta", "soru_tipi": "eksik diyalog", "yonerge": "Hale is a new student. Write Sinan's answers. Use your own ideas.", "uyaran": [{"tur": "diyalog", "konusmalar": [{"kisi": "Hale", "soz": "Hi! Where is the canteen?"}, {"kisi": "Sinan", "soz": "(1)"}, {"kisi": "Hale", "soz": "What time is lunch?"}, {"kisi": "Sinan", "soz": "(2)"}, {"kisi": "Hale", "soz": "How often do you go to the library?"}, {"kisi": "Sinan", "soz": "(3)"}, {"kisi": "Hale", "soz": "What do you do after school?"}, {"kisi": "Sinan", "soz": "(4)"}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-6-s5-08.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(1)", "cevap": "It is near the garden.", "kabul": ["It is in the school."], "aciklama": "Where sorusu yer ister. Okulda gerçekten olabilecek, anlaşılır bir yer (garden, library, lunch hall) yazılır."}, {"soru": "(2)", "cevap": "It is at 12:00.", "kabul": ["Lunch is at 12:00."], "aciklama": "What time sorusu saat ister; \"It is at ...\" kalıbı kullanılır."}, {"soru": "(3)", "cevap": "I often go to the library.", "kabul": ["I go to the library on Fridays."], "aciklama": "How often sorusu sıklık ister; always / often / sometimes / never ile cevap verilir."}, {"soru": "(4)", "cevap": "I do my homework.", "kabul": ["I study in the library.", "I play chess with my friends."], "aciklama": "What do you do sorusu bir eylem ister. Okul sonrası yapılan, anlaşılır bir eylem yazılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: soruya uygun, anlaşılır her cevap tam puan alır. Çözüm: önce Hale'in sorusunu oku, sonra Sinan'ın ağzından kısa ve doğru bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fridays:SARTLI", "sinan's:SARTLI"]}, "ornek": "Where is the library? → It is near the lab."}]}, {"kod": "7-s1", "sinif": 7, "ders": "secmeli", "senaryo": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 1}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 1}, {"kod": "E7.2.W1", "tema": "Sports", "metin": "Students will be able to write pieces about routines/daily activities by using frequency adverbs.", "adet": 1}], "sorular": [{"id": "HZ-7-s1-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Kevin and Joe are best friends. They are very different. Kevin is tall and slim. He has short, straight, black hair and brown eyes. He is hardworking, so his marks are higher than Joe's marks. Joe is shorter than Kevin, but he is funnier. Joe is outgoing, and he has a lot of friends because he is friendly. Kevin is not very outgoing. He likes reading books at home.", "baslik": "Two Best Friends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Kevin is shorter than Joe.", "cevap": "Kevin is taller than Joe.", "kabul": ["Joe is shorter than Kevin.", "Kevin is taller."], "aciklama": "Metinde \"Joe is shorter than Kevin\" yazıyor. Yani Kevin daha uzun: \"taller than\"."}, {"soru": "Joe is hardworking, so his marks are higher than Kevin's marks.", "cevap": "Kevin is hardworking, so his marks are higher than Joe's marks.", "kabul": ["Kevin's marks are higher than Joe's marks.", "Joe's marks are worse than Kevin's marks."], "aciklama": "Metindeki \"He is hardworking, so his marks are higher than Joe's marks\" cümlesinde \"He\" Kevin'dir. Yanlış kişi Joe yazılmış."}, {"soru": "Kevin is more outgoing than Joe.", "cevap": "Joe is more outgoing than Kevin.", "kabul": ["Kevin is not very outgoing."], "aciklama": "Metinde \"Joe is outgoing\" ve \"Kevin is not very outgoing\" yazıyor. Karşılaştırma: \"Joe is more outgoing than Kevin\"."}, {"soru": "Kevin has long, curly hair.", "cevap": "Kevin has short, straight hair.", "kabul": ["Kevin has short, straight, black hair.", "He has short, straight hair."], "aciklama": "Metinde \"He has short, straight, black hair\" yazıyor. Saç tarifi (short, straight) metinden alınır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cümle metne uygun düzeltilmişse tam puan; yazım ve küçük dilbilgisi hatası puan kırdırmaz; cümle yanlış kalmışsa ya da yanlış kişi/bilgi yazılmışsa puan yok. Çözüm: önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır ve yanlış olan kısmı metne göre değiştir.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["joe's:SARTLI", "kevin's:SARTLI"]}}, {"id": "HZ-7-s1-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "tabloya göre karşılaştırma cümleleri", "yonerge": "Look at the chart. Compare Nazan and Mehmet. Write sentences.", "uyaran": [{"tur": "tablo", "basliklar": ["", "Nazan", "Mehmet"], "satirlar": [["age", "14", "15"], ["height", "160 cm", "172 cm"], ["weight", "55 kg", "52 kg"], ["marks", "95", "80"], ["friends", "5", "12"], ["character", "hardworking", "outgoing"]], "baslik": "Nazan and Mehmet"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-7-s1-02.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(height)", "cevap": "Mehmet is taller than Nazan.", "kabul": ["Nazan is shorter than Mehmet."], "aciklama": "Mehmet 172 cm, Nazan 160 cm. Kısa sıfat + -er + than: \"taller than\" / \"shorter than\"."}, {"soru": "(weight)", "cevap": "Nazan is heavier than Mehmet.", "kabul": ["Mehmet is slimmer than Nazan.", "Mehmet is thinner than Nazan."], "aciklama": "Nazan 55 kg, Mehmet 52 kg. Nazan daha ağır: \"heavier than\". Mehmet için \"slimmer / thinner than\" da olur."}, {"soru": "(marks)", "cevap": "Nazan's marks are higher than Mehmet's marks.", "kabul": ["Nazan's marks are higher than Mehmet's.", "Mehmet's marks are worse than Nazan's marks."], "aciklama": "Nazan 95, Mehmet 80 almış. Notlar için \"higher than\" kullanılır."}, {"soru": "(friends / because)", "cevap": "Mehmet has more friends than Nazan because he is outgoing.", "kabul": ["Mehmet has more friends because he is outgoing.", "Mehmet has 12 friends, but Nazan has 5 friends, because he is more outgoing."], "aciklama": "Mehmet 12, Nazan 5 arkadaşa sahip. Nedeni \"because\" ile tablodaki karakter satırından yaz: Mehmet outgoing."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Bilgi tabloya uygun ve karşılaştırma yapısı (-er ... than / more ... than) doğruysa tam puan; bilgi doğru ama yapı ya da ad hatalıysa yarım puan; bilgi yanlışsa puan yok. Çözüm: önce tablodaki iki değere bak, hangisinin daha büyük/fazla olduğunu bul, sonra örnekteki gibi cümle kur.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["character:KOK", "mehmet's:SARTLI", "nazan's:SARTLI"]}, "ornek": "(age) Mehmet is older than Nazan."}, {"id": "HZ-7-s1-03", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the text. Who says these sentences? Write the names.", "uyaran": [{"tur": "metin", "metin": "Helen, Robert, Ali and Sally are friends. Helen is a swimmer. She trains at the swimming pool three times a week, and she always eats a big breakfast. Robert prefers team sports. He plays basketball for the school team, and he works out at the gym twice a week. Ali doesn't like exercises. He seldom does sports, but he watches matches on TV every weekend. Sally wakes up early every morning and goes jogging in the park. She never eats junk food.", "baslik": "Four Friends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I play with my school team.\"", "cevap": "Robert", "kabul": [], "aciklama": "\"He plays basketball for the school team\" cümlesi Robert hakkında. Okul takımında oynayan tek kişi o."}, {"soru": "\"I run in the park every morning.\"", "cevap": "Sally", "kabul": [], "aciklama": "\"Sally wakes up early every morning and goes jogging in the park.\" Parkta koşan tek kişi Sally."}, {"soru": "\"I go swimming three times a week.\"", "cevap": "Helen", "kabul": [], "aciklama": "Metinde yalnız Helen yüzücü ve havuzda haftada üç kez antrenman yapıyor (\"trains at the swimming pool three times a week\")."}, {"soru": "\"I do not often exercise.\"", "cevap": "Ali", "kabul": [], "aciklama": "Metinde Ali için \"He seldom does sports\" yazıyor; \"seldom\" ile \"not often\" aynı anlama gelir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce metni oku, sonra cümledeki bilgiyi metinde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["matches:SARTLI", "says:SARTLI", "watches:SARTLI", "weekend:KOK", "works:SARTLI"]}}, {"id": "HZ-7-s1-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.W1", "zorluk": "orta", "soru_tipi": "çizelge → sıklık zarfı cümleleri", "yonerge": "Look at Rachel's chart. Write sentences about Rachel. Use frequency adverbs.", "uyaran": [{"tur": "tablo", "basliklar": ["Activity", "How often?"], "satirlar": [["wake up early", "always"], ["eat fruit", "usually"], ["play basketball", "twice a week"], ["watch a match", "sometimes"], ["eat junk food", "never"]], "baslik": "Rachel's Routine"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-7-s1-04.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(eat fruit)", "cevap": "Rachel usually eats fruit.", "kabul": [], "aciklama": "Tabloda \"usually\" yazıyor. Sıklık zarfı özneden sonra, fiilden önce gelir; Rachel tekil olduğu için \"eats\"."}, {"soru": "(play basketball)", "cevap": "Rachel plays basketball twice a week.", "kabul": ["Rachel plays basketball two times a week."], "aciklama": "\"Twice a week\" cümlenin sonuna yazılır."}, {"soru": "(watch a match)", "cevap": "Rachel sometimes watches a match.", "kabul": [], "aciklama": "\"Sometimes\" özneden sonra gelir; \"watch\" fiili 3. tekilde \"watches\" olur."}, {"soru": "(eat junk food)", "cevap": "Rachel never eats junk food.", "kabul": [], "aciklama": "\"Never\" kendi başına olumsuz anlam taşır. Fiil: \"eats\"."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Bilgi tabloya uygun, sıklık zarfı (ya da once / twice / times a week) doğru yerde ve fiil doğru biçimdeyse (3. tekil -s) tam puan; bilgi doğru ama dil hatalıysa yarım puan; bilgi yanlışsa puan yok. Çözüm: önce tablodaki sıklığa bak, sonra örnekteki gibi ad + sıklık zarfı + fiil sırasıyla yaz.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["rachel's:SARTLI", "watches:SARTLI"]}, "ornek": "(wake up early) Rachel always wakes up early."}]}, {"kod": "7-s2", "sinif": 7, "ders": "ingilizce", "senaryo": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 2}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 2}], "sorular": [{"id": "HZ-7-s2-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Read the sentences from a dialogue. Complete the chart with A, B, C, D, E or F to make the correct dialogue.", "uyaran": [{"tur": "metin", "metin": "A) What is he like?\nB) Who is that boy, Sophie?\nC) He is tall and slim. He has short, straight hair.\nD) What does he look like?\nE) He is Jim. He is my best friend.\nF) He is patient and helpful. He is funnier than me!", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "F"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "Birinci satır \"Who is that boy?\" sorusudur; cevabı onu tanıtan \"He is Jim. He is my best friend.\" cümlesidir. Soru ile cevap yan yana gelir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "Kişi tanıtıldıktan sonra görünüşü sorulur: \"What does he look like?\" (look like = neye benziyor / nasıl görünüyor)."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "\"What does he look like?\" sorusunun cevabı boy, vücut ve saç anlatan \"He is tall and slim. He has short, straight hair.\" cümlesidir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "Son cevap kişiliği anlatır (\"patient and helpful\"), bu yüzden hemen önceki soru kişiliği soran \"What is he like?\" olmalıdır."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan, yanlış ya da boş harf puan almaz. Çözüm yolu: önce ilk ve son satırı oku; her soruyu, hemen ardından gelen cevapla eşleştir; sonra sırayı baştan sona oku.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-7-s2-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Rachel and Helen are sisters. Rachel is older than Helen, but they are very different. Rachel is tall and slim. She has long, straight, blonde hair and blue eyes. She is polite and hardworking. Helen is shorter than Rachel. She has curly, brown hair and green eyes. Helen is more outgoing than her sister, and she is very funny. She has a lot of friends.", "baslik": "Two Sisters"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Helen's eyes are not blue. They are ......... .", "cevap": "green", "kabul": [], "aciklama": "Metinde Helen için \"curly, brown hair and green eyes\" yazıyor; Rachel'ın gözleri mavi, Helen'ın gözleri yeşil."}, {"soru": "Rachel is not plump. She is ......... .", "cevap": "slim", "kabul": [], "aciklama": "Rachel için \"tall and slim\" yazıyor. plump = tombul; slim (ince) bunun zıttıdır."}, {"soru": "Rachel works hard. She is ......... .", "cevap": "hardworking", "kabul": [], "aciklama": "Metinde Rachel için \"She is polite and hardworking.\" cümlesi var. works hard = hardworking."}, {"soru": "Rachel's hair is not curly. It is ......... .", "cevap": "straight", "kabul": [], "aciklama": "Rachel'ın saçı için \"long, straight, blonde hair\" yazıyor; curly (kıvırcık) olan Helen'ın saçıdır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; küçük yazım hatası (tek harf) kabul edilir, yanlış kelime puan almaz. Çözüm yolu: önce metni oku; her cümlenin ipucunu (saç, göz, yapı, kişilik) metinde ara ve cümlenin anlamına uyan kelimeyi bul.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["helen's:SARTLI", "rachel's:SARTLI", "sisters:SARTLI", "works:SARTLI"]}}, {"id": "HZ-7-s2-03", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "cümle başlangıçlarını tamamlama", "yonerge": "Complete the sentences about you and your family.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "I am younger than ", "cevap": "my brother.", "kabul": ["my sister.", "my father."], "aciklama": "Karşılaştırmada younger than + kişi kullanılır. \"I am younger than my brother.\" gibi mantıklı herhangi bir kişi yazılabilir."}, {"soru": "My best friend is more ", "cevap": "outgoing than me.", "kabul": ["hardworking than me.", "intelligent than me."], "aciklama": "more + uzun sıfat + than yapısı gerekir (more outgoing than)."}, {"soru": "My mother is shorter than ", "cevap": "my father.", "kabul": ["me.", "my sister."], "aciklama": "Kısa sıfat + er + than: shorter than. Sonra bir kişi yazılır (my father, me...)."}, {"soru": "My best friend has curly hair, but ", "cevap": "I have straight hair.", "kabul": ["my brother has straight hair.", "I have short hair."], "aciklama": "but ile iki kişiyi (ya da kendini) karşılaştıran bir cümle yazılır: curly hair <-> straight hair gibi bir zıtlık verilir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: cümle başlangıcına dilbilgisi olarak uyan ve anlamlı her cevap tam puan alır (karşılaştırmada -er / more ... than doğru kullanılmalı); anlamsız ya da başlangıca uymayan cevap puan almaz. Çözüm yolu: önce örneği oku; sonra cümlenin başını ve sonunu yüksek sesle birleştirerek anlamlı olup olmadığına bak.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "My friend is funnier than my brother."}, {"id": "HZ-7-s2-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Answer the questions.", "uyaran": [{"tur": "metin", "metin": "Zeynep is a talented tennis player. She trains at the tennis court three times a week. She plays with her coach, Mr Robins, on Sundays. Zeynep eats fruit, vegetables and meat, and she never eats junk food. She doesn't like running, but she likes swimming. Last year, she won a gold medal in a national championship.", "baslik": "Zeynep's Sport"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-7-s2-04.jpg", "yerlesim": "yan"}, "alt_sorular": [{"soru": "Does Zeynep train three times a week?", "cevap": "Yes, she does.", "kabul": ["Yes.", "Yes, she trains three times a week."], "aciklama": "Metindeki \"She trains at the tennis court three times a week.\" cümlesi soruyla uyuşur; cevap Yes. \"Does\" ile sorulan soruya \"Yes, she does.\" denir."}, {"soru": "Does Zeynep like swimming?", "cevap": "Yes, she does.", "kabul": ["Yes.", "Yes, she likes swimming."], "aciklama": "Metinde \"She doesn't like running, but she likes swimming.\" cümlesi var; koşmayı sevmez ama yüzmeyi sever. Cevap Yes."}, {"soru": "Is Zeynep a swimmer?", "cevap": "No, she is not. She is a tennis player.", "kabul": ["No. She is a tennis player.", "No, she isn't. She is a tennis player."], "aciklama": "Metin \"Zeynep is a talented tennis player.\" diyor; Zeynep tenis oyuncusudur. Yes/No sorusu \"Is\" ile başlar, kısa cevap \"No, she is not.\" olur."}, {"soru": "Does Zeynep eat junk food?", "cevap": "No, she does not. She never eats junk food.", "kabul": ["No. She never eats junk food.", "No, she doesn't."], "aciklama": "Metinde \"she never eats junk food\" yazıyor; never = hiçbir zaman, yani cevap No."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Yes/No doğru ve (No ise) düzeltme metne uygunsa tam puan; yalnız doğru Yes ya da No yazılmışsa yarım puan. Yazım ve dilbilgisi hatası puan kırdırmaz. Çözüm yolu: önce soruyu oku; cevabı metinde ara; bilgi doğruysa Yes, değilse No yaz ve No ise metindeki doğru bilgiyi ikinci cümlede ver.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["zeynep's:SARTLI"]}, "ornek": "Does Zeynep play with her friends on Sundays? → No, she does not. She plays with her coach."}, {"id": "HZ-7-s2-05", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "paragraf cümlelerini sıralama", "yonerge": "Read the sentences. Make the correct paragraph. Write A, B, D or E in the chart.", "uyaran": [{"tur": "metin", "metin": "A) In the evening, he rests at home and watches TV.\nB) After that, they train for two hours.\nC) First, Sam wakes up early and eats a big breakfast.\nD) After training, Sam takes a shower and eats lunch.\nE) Then, he goes to the football field with his team.", "baslik": "Sam's Football Day"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5"], "satirlar": [[{"ornek": "C"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "İlk cümleden sonra \"Then\" gelir: Sam kahvaltı yaptıktan sonra takımıyla sahaya gider. \"Then\" bir olaydan sonraki olayı anlatır."}, {"soru": null, "cevap": "B", "kabul": [], "aciklama": "\"After that\" bir önceki olaydan (sahaya gitme) sonra olanı anlatır: they train for two hours (antrenman yaparlar)."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "\"After training\" antrenmandan sonra demektir; bu yüzden antrenman cümlesinden hemen sonra gelir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "\"In the evening\" günün sonudur; en son olay evde dinlenmek ve TV izlemektir."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan. Çözüm yolu: First, Then, After that, After training, In the evening gibi sıra sözcüklerini ara; olayları günün akışına göre diz ve ilk kutudaki örnekten başla.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["rests:SARTLI", "sam's:SARTLI", "takes:SARTLI", "watches:SARTLI"]}}]}, {"kod": "8-s4", "sinif": 8, "ders": "ingilizce", "senaryo": 4, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E8.1.R1", "tema": "Friendship", "metin": "Students will be able to understand short and simple texts about friendship.", "adet": 1}, {"kod": "E8.1.R2", "tema": "Friendship", "metin": "Students will be able to understand short and simple invitation letters, cards and e-mails.", "adet": 2}, {"kod": "E8.2.R1", "tema": "Teen Life", "metin": "Students will be able to understand short and simple texts about regular activities of teenagers.", "adet": 2}, {"kod": "E8.2.W1", "tema": "Teen Life", "metin": "Students will be able to write a short and simple paragraph about regular activities of teenagers.", "adet": 1}], "sorular": [{"id": "HZ-8-s4-01", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R1", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Mert. Rick is my best friend. We are neighbours and we go to the same school. Rick is honest and punctual. He is always on time, but I am always in a hurry. On Sundays, we play tennis together. Then, we eat pizza at my house. I trust Rick because he never tells lies.", "baslik": "My Best Friend"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mert and Rick go to different schools.", "cevap": "Mert and Rick go to the same school.", "kabul": ["They go to the same school."], "aciklama": "Metinde \"we go to the same school\" yazıyor. Yanlış cümlede \"different\" kullanılmış; doğrusu \"the same\"."}, {"soru": "Rick is always in a hurry.", "cevap": "Mert is always in a hurry.", "kabul": ["Rick is always on time."], "aciklama": "Metinde \"He is always on time, but I am always in a hurry\" yazıyor. Acelesi olan kişi metni anlatan Mert; \"He\" Rick'tir."}, {"soru": "Mert and Rick play tennis on Saturdays.", "cevap": "Mert and Rick play tennis on Sundays.", "kabul": ["They play tennis on Sundays."], "aciklama": "Metindeki \"On Sundays, we play tennis together\" cümlesi. Doğru gün Sundays."}, {"soru": "They eat pizza at Rick's house.", "cevap": "They eat pizza at Mert's house.", "kabul": ["They eat pizza at Mert's.", "Mert and Rick eat pizza at Mert's house."], "aciklama": "Metinde \"we eat pizza at my house\" yazıyor; \"my\" metni anlatan Mert demektir. Rick'e ait sanmak."}], "adlar": ["Mert", "Rick", "Rick's", "Mert's"], "puanlama": "Alt sorular eşit puanlı. Cümle metne uygun düzeltilmişse tam puan; yazım ve küçük dilbilgisi hatası puan kırdırmaz; cümle yanlış kalmışsa ya da yanlış kişi/bilgi yazılmışsa puan yok. Çözüm: önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır ve yanlış olan kısmı metne göre değiştir.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["saturdays:SARTLI", "schools:SARTLI", "sundays:SARTLI"]}}, {"id": "HZ-8-s4-02", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "davetiye bilgi tablosu", "yonerge": "Read the e-mail. Then complete the invitation.", "uyaran": [{"tur": "metin", "metin": "Hi Jim,\nHow are you? I'm giving a picnic on Sunday for my friends. We will meet at 2 o'clock in front of the museum. We will eat pizza and drink orange juice. Would you like to come? Please, let me know soon.\nOya", "baslik": "E-mail"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["From", {"bosluk": 1}], ["Day", {"bosluk": 2}], ["Time", {"bosluk": 3}], ["Meet", {"bosluk": 4}], ["Drink", {"bosluk": 5}]], "baslik": "PICNIC"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Oya", "kabul": [], "aciklama": "E-postanın son satırında gönderenin adı yazıyor: \"Oya\"."}, {"soru": null, "cevap": "Sunday", "kabul": ["on Sunday"], "aciklama": "\"I'm giving a picnic on Sunday\" cümlesi. Gün bilgisi \"on\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "2 o'clock", "kabul": ["at 2 o'clock"], "aciklama": "\"We will meet at 2 o'clock\" cümlesi. Saat bilgisi \"at\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "in front of the museum", "kabul": ["the museum", "at the museum"], "aciklama": "\"We will meet ... in front of the museum\" cümlesi. Buluşma yeri \"in front of the museum\"."}, {"soru": null, "cevap": "orange juice", "kabul": ["juice"], "aciklama": "\"We will eat pizza and drink orange juice.\" Yiyecek pizza, içecek orange juice; \"Drink\" satırına içecek yazılır."}], "adlar": ["Oya", "Jim"], "puanlama": "Kutular eşit puanlı. Bilgi e-postadan doğru aktarılmışsa tam puan; yazım hatası puan kırdırmaz; bilgi yanlışsa ya da boşsa puan yok. Çözüm: önce e-postayı oku, sonra her kutunun başlığına uyan bilgiyi (kim, hangi gün, saat, buluşma yeri, içecek) metinde ara.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["e-mail:KOK"]}}, {"id": "HZ-8-s4-03", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the invitation letter. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi Tina,\nOur sports club has a tennis match at the stadium next Saturday. Would you like to come and support us? My cousin Robin will come too. Then, we will have a party at the club with cake and juice. Please, reply before Friday.\nTony", "baslik": "Letter"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Tony's club has a ......... match.", "cevap": "tennis", "kabul": [], "aciklama": "Mektubun ilk cümlesinde \"a tennis match\" yazıyor. Maçın türü tenis."}, {"soru": "Tina can watch the game at the ......... .", "cevap": "stadium", "kabul": [], "aciklama": "\"... match at the stadium\" ifadesi. \"game\" ve \"match\" aynı anlamda kullanılmış."}, {"soru": "Robin is Tony's ......... .", "cevap": "cousin", "kabul": [], "aciklama": "\"My cousin Robin will come too\" cümlesi. Mektubu yazan Tony olduğu için \"my cousin\" = Tony'nin kuzeni."}, {"soru": "Tina should answer before ......... .", "cevap": "Friday", "kabul": [], "aciklama": "\"Please, reply before Friday.\" Burada \"reply\" ve \"answer\" aynı anlamda; cevap verilecek gün Friday."}], "adlar": ["Tina", "Tony", "Tony's", "Robin"], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; kelimede küçük yazım hatası kabul edilir; yanlış kelime ya da boş cevap puan kazandırmaz. Çözüm: önce cümleyi oku, sonra cümledeki bilgiyi mektupta ara ve boşluğa oradaki kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-8-s4-04", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Put the sentences in the correct order and make a dialogue. Write the letters in the boxes.", "uyaran": [{"tur": "metin", "metin": "A) Yes, I am. I love playing basketball.\nB) Sure, I'd love to.\nC) How often do you play it?\nD) Would you like to join us on Saturday?\nE) Are you keen on sports, Ali?\nF) I usually play it with my friends three days a week.", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "E"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "B"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "A", "kabul": [], "aciklama": "İlk cümle \"Are you keen on sports, Ali?\" sorusu; cevabı \"Yes, I am.\" ile başlayan A cümlesi."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "A cümlesinde basketbol geçiyor. \"it\" basketbolu gösterir; \"How often do you play it?\" soruyu sürdürür."}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "\"How often\" sorusunun cevabı sıklık bildirir: \"three days a week\". \"it\" yine basketbolu gösterir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "F cümlesinde \"my friends\" geçiyor; \"join us\" bu arkadaşlara katılma daveti. Son cümle B (\"Sure, I'd love to.\") bu davete cevap."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan. Çözüm: önce ilk ve son cümleye bak; sonra soru–cevap çiftlerini bul (\"Are you keen on...?\" → \"Yes, I am.\"; \"it\" ve \"us\" gibi sözcükler önceki cümleyi gösterir).", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["letters:SARTLI"]}}, {"id": "HZ-8-s4-05", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the text. Who says these sentences? Write the names.", "uyaran": [{"tur": "metin", "metin": "Some teenagers talk about their weekends. James is keen on cycling. He goes cycling with his sister on Sundays. Doris is fond of reading. She reads detective books in the evenings. Sam loves chess. He plays it online every Saturday. Kelly enjoys watching films. She often goes to the cinema with her cousin.", "baslik": "Weekends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I enjoy reading detective stories.\"", "cevap": "Doris", "kabul": [], "aciklama": "\"She reads detective books in the evenings\" cümlesi Doris hakkında. \"stories\" ve \"books\" burada benzer anlamda."}, {"soru": "\"I often visit the cinema with my cousin.\"", "cevap": "Kelly", "kabul": [], "aciklama": "\"She often goes to the cinema with her cousin\" cümlesi Kelly hakkında. Kuzeniyle sinemaya giden tek kişi o."}, {"soru": "\"I like cycling with my sister at the weekend.\"", "cevap": "James", "kabul": [], "aciklama": "\"He goes cycling with his sister on Sundays.\" Kız kardeşiyle bisiklete binen tek kişi James; \"weekend\" Sunday'i kapsar."}, {"soru": "\"I love playing chess on the internet.\"", "cevap": "Sam", "kabul": [], "aciklama": "\"He plays it online every Saturday\" cümlesinde \"it\" satrançtır. \"online\" ile \"on the internet\" aynı anlama gelir."}], "adlar": ["James", "Doris", "Sam", "Kelly"], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce metni oku, sonra cümledeki bilgiyi metinde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["enjoys:SARTLI", "plays:SARTLI", "reads:SARTLI", "sundays:SARTLI"]}}, {"id": "HZ-8-s4-06", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.W1", "zorluk": "orta", "soru_tipi": "notlardan sıralı yazma", "yonerge": "Read the notes. Doris does these things every Saturday. Write about her. Complete the sentences.", "uyaran": [{"tur": "tablo", "basliklar": ["Time", "Doris"], "satirlar": [["9:00", "play basketball with friends"], ["11:00", "go shopping"], ["3:00", "read detective books"], ["7:00", "watch a film with her sister"]], "baslik": "Doris's Saturdays"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": "sira"}, "alt_sorular": [{"soru": "In the morning, ", "cevap": "In the morning, Doris plays basketball with her friends at 9:00.", "kabul": ["In the morning, she plays basketball with her friends at 9:00.", "In the morning, Doris plays basketball at 9:00."], "aciklama": "Notlardaki ilk satır: 9:00 – play basketball with friends. Saat bilgisi \"at 9:00\" ile eklenir, fiil 3. tekil kişide \"plays\" olur.", "foto": "HZ-8-s4-06_1.jpg"}, {"soru": "Then, ", "cevap": "Then, Doris goes shopping at 11:00.", "kabul": ["Then, she goes shopping at 11:00."], "aciklama": "İkinci satır: 11:00 – go shopping. \"go\" fiili Doris ile \"goes\" olur.", "foto": "HZ-8-s4-06_2.jpg"}, {"soru": "After that, ", "cevap": "After that, Doris reads detective books at 3:00.", "kabul": ["After that, she reads detective books at 3:00."], "aciklama": "Üçüncü satır: 3:00 – read detective books. \"read\" fiili 3. tekil kişide \"reads\" olur.", "foto": "HZ-8-s4-06_3.jpg"}, {"soru": "In the evening, ", "cevap": "In the evening, Doris watches a film with her sister at 7:00.", "kabul": ["In the evening, she watches a film with her sister at 7:00.", "In the evening, Doris watches a film with her sister."], "aciklama": "Son satır: 7:00 – watch a film with her sister. Notlarda \"her sister\" yazıyor; \"watch\" fiili \"watches\" olur.", "foto": "HZ-8-s4-06_4.jpg"}], "adlar": ["Doris", "Kelly"], "puanlama": "Satırlar eşit puanlı. Satır başı verilen sözcükle, notlardaki bilgiyi doğru yazan ve fiili doğru biçimde (3. tekil -s) kullanan cümle tam puan; bilgi doğru ama dil hatalıysa yarım puan; bilgi yanlışsa ya da boşsa puan yok. Çözüm: önce notları oku, sonra her satır başını örnekteki gibi tamamla: saat bilgisini \"at ...\" ile, etkinliği Doris ile 3. tekil kişi biçiminde yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["plays:SARTLI", "reads:SARTLI", "saturdays:SARTLI", "watches:SARTLI"]}, "ornek": "Notes: Kelly, 8:00, go cycling → At 8:00, Kelly goes cycling."}]}];
